// Independent samples from the original executable, not generated by these equations.
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {coefficients,liftSample,thrustSample,wheelSample} from '../src/flight-math.js';
const fixture=JSON.parse(await fs.readFile(new URL('../content/flight-native-checks.json',import.meta.url),'utf8'));
for(const {kind,input,expected} of fixture.cases){
 const got=kind==='coefficients'?coefficients(input.id,input.mach):({lift:liftSample,thrust:thrustSample,wheel:wheelSample}[kind])(input);
 for(const [key,want] of Object.entries(expected)){
  const context=`${kind} ${JSON.stringify(input)}: ${key}, wanted ${want}, got ${got[key]}`;
  if(typeof want==='number')assert(Number.isFinite(got[key])&&Math.abs(got[key]-want)<=1e-9*Math.max(1,Math.abs(want)),context);
  else assert.equal(got[key],want,context);
 }
}
console.log(`Checked flight diagrams against ${fixture.cases.length} original-code examples.`);
